-- ============================================================================
-- payer-rules-oh-carecoord-absent.sql
--
-- Five codes Ohio Medicaid's Appendix DD does not list anywhere: principal care
-- management (99424-99427) and home health care supervision (G0181). All five
-- Ohio Medicaid plans answered nothing for them.
--
-- THE TWO HALVES GET OPPOSITE ANSWERS, AND THAT IS THE POINT
-- Absence means different things in this document depending on the code range.
-- The schedule carries a blanket exclusion note:
--
--   "Unless otherwise indicated, services and items represented by codes in the following ranges are not covered."
--   G0001-G9999, P0001-P9999, S0199-S4980, S5015-S5549, S5567-S9999, T0001-T2101, W0001-W9999, X0001-X9999, XX001-XX010, Y0001-Y9999, Z0001-Z9999
--
-- Every enumerated range is a letter series. G0181 sits inside G0001-G9999, so
-- its absence IS a determination: not covered. 99424-99427 are 99xxx CPT codes
-- and no 99xxx range appears in that list, so their absence determines nothing
-- and they are recorded as unknown.
--
-- An earlier version of this file got that backwards and recorded G0181 as
-- unknown, reasoning that these codes "cannot be shown to fall inside" the
-- enumerated ranges. G0181 falls inside the very first one. The error was
-- visible in the library as an inconsistency: G0179 and G0180 — the sibling
-- home-health certification codes, equally absent — already read not_covered
-- from this same sentence, so one document was producing two answers.
--
-- HOW ABSENCE WAS PROVED
-- Not by a failed search. The workbook has 8 tabs and 9,617 distinct
-- codes; for each code the two that WOULD surround it are consecutive:
--
--   99424-99427   99423 (Ol dig e/m svc 21+ min) -> 99429 (Unlisted preventive medicine service)
--   G0181         G0138 (Iv cipaglucosidase alfa-atga) -> G0202 (Screening mammography, digital, bilateral, all views)
--
-- and the literal strings "99424".."99427" and "G0181" do not occur anywhere in
-- the archive at all — not in a sheet, not in sharedStrings, not as an orphan
-- left by a deleted row. A zero-hit search can mean "absent" or "my query was
-- wrong"; a populated bracket plus a zero raw-byte count can only mean absent.
--
-- READ THIS BEFORE TRUSTING ANY "OHIO REMOVED A CODE" CLAIM
-- A previous seed asserted Ohio had DELETED 30 codes and re-grounded 150 rules
-- on it. That was false and has been reverted. Its parser could not see
-- self-closing cells (<c r="B10022" s="76"/>), so empty cells shifted every
-- following value into the wrong column and 68 G-codes went invisible. This
-- file is generated by a parser that walks <row> elements and maps each cell to
-- its true column from the r attribute, and it re-checks every claim above
-- against the workbook before it will write itself.
-- ============================================================================

BEGIN;

UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2026-01-01')
 WHERE pr.expiration_date IS NULL
   AND pr.created_by <> 'extract:oh-carecoord-absent-2026-08'
   AND pr.state = 'OH' AND pr.attribute = 'covered'
   AND pr.code IN ('99424', '99425', '99426', '99427', 'G0181')
   AND pr.payer_id IN ('a0000000-0000-4000-8000-000000000306'::uuid, 'a0000000-0000-4000-8000-000000000305'::uuid, 'a0000000-0000-4000-8000-000000000308'::uuid, 'a0000000-0000-4000-8000-000000000307'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid);

INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
